class Cart:
    """A shopping cart keyed by SKU."""

    def __init__(self):
        self.items = {}  # sku -> (unit_price, quantity)

    def add_item(self, sku, unit_price, quantity=1):
        if quantity <= 0:
            raise ValueError("quantity must be positive")
        if sku in self.items:
            existing_price, existing_qty = self.items[sku]
            # Preserve the original unit price; quantities accumulate
            self.items[sku] = (existing_price, existing_qty + quantity)
        else:
            self.items[sku] = (unit_price, quantity)

    def remove_item(self, sku, quantity=1):
        if sku not in self.items:
            raise KeyError(f"SKU {sku} not in cart")
        unit_price, current = self.items[sku]
        new_qty = current - quantity
        if new_qty <= 0:
            del self.items[sku]
        else:
            self.items[sku] = (unit_price, new_qty)

    def subtotal(self):
        return round(sum(price * quantity for price, quantity in self.items.values()), 2)

    def item_count(self):
        return sum(quantity for _, quantity in self.items.values())

