def charge(amount_cents, card_token):
    """Charge a card through the gateway and return the transaction id."""
    payload = json.dumps({"amount": amount_cents / 100, "card": card_token}).encode()
    request = urllib.request.Request(
        GATEWAY_URL,
        data=payload,
        headers={"Content-Type": "application/json"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(request, timeout=3) as response:
            body = json.load(response)
    except (URLError, TimeoutError) as e:
        raise RuntimeError("Gateway connection error") from e
    except ValueError as e:
        raise ValueError("Malformed JSON response") from e
    if "receipt_id" not in body:
        raise ValueError("Missing transaction id")
    receipt_id = body["receipt_id"]
    if not isinstance(receipt_id, str) or not receipt_id.startswith("txn_"):
        raise ValueError("Invalid transaction id")
    return receipt_id

